import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 15 · Swap and lending","description":"","frontmatter":{},"headers":[],"relativePath":"modules/15-defi.md","filePath":"modules/15-defi.md","lastUpdated":1790431304000}'),s={name:"modules/15-defi.md"};function n(r,e,l,d,h,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="module-15-·-swap-and-lending" tabindex="-1">Module 15 · Swap and lending <a class="header-anchor" href="#module-15-·-swap-and-lending" aria-label="Permalink to &quot;Module 15 · Swap and lending&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contracts</strong></td><td><code>GrainToken.sol</code>, <code>TownSwap.sol</code>, <code>GrainLoans.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Exchange</td></tr><tr><td><strong>Patterns</strong></td><td>Constant-product AMM; over-collateralised lending</td></tr><tr><td><strong>Stamp</strong></td><td>Module 15 (on a swap, and on a borrow)</td></tr></tbody></table><blockquote><p>⚠ <strong><code>GrainLoans</code> contains a deliberate vulnerability.</strong> It is the point of the module. Do not copy it into anything real, and read the attack section before you read anything else.</p></blockquote><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Two problems, and the second only exists because of how we solve the first.</p><p><strong>Exchange.</strong> A farmer has GRAIN and wants TVD. An order book needs a matched counterparty at a matched price at a matched moment, and on a small market that counterparty is usually not there.</p><p><strong>Credit.</strong> A farmer with GRAIN wants TVD without selling — the harvest is next month, the bill is today. Lending needs collateral, and collateral needs a <strong>price</strong>.</p><p>Where does a smart contract get a price?</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p><strong>An AMM.</strong> No order book, no counterparty — a pool holding both tokens and a formula. <code>x · y = k</code>: the product of the reserves never falls. Put TVD in, the formula says how much GRAIN comes out. Anyone can trade at any size at any time, and the price is whatever the reserves say it is.</p><p><strong>Over-collateralised lending.</strong> Deposit GRAIN, borrow up to 50% of its value in TVD. Debt above 70% and anyone may liquidate you, paying off part of your debt and taking collateral plus a 10% bonus.</p><p>And the trap: <strong>the lending contract reads the AMM&#39;s spot price.</strong> It is the obvious source — it is on chain, it is free, it is right there. It is also the thing the borrower can move.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>AMM.</strong> Automated market maker: a contract that quotes both sides from a formula over its reserves.</p><p><strong>Constant product.</strong> <code>reserveIn · reserveOut = k</code>, Uniswap V2&#39;s invariant. <code>k</code> only grows, by the fees.</p><p><strong>Slippage.</strong> Your trade moves the price against you. Big trades in small pools get bad fills — not a bug, arithmetic.</p><p><strong>Liquidity provider.</strong> Someone who deposits both tokens and earns a share of fees. They carry impermanent loss.</p><p><strong>LTV / liquidation threshold / bonus.</strong> 5000 / 7000 / 1000 basis points here: borrow up to 50%, liquidatable at 70%, liquidator takes a 10% premium.</p><p><strong>Health factor.</strong> Below 1e18 means liquidatable. The number a borrower watches.</p><p><strong>Spot price.</strong> The price implied by reserves <em>right now</em>. <strong>Not a price feed.</strong> This distinction is the whole module.</p><p><strong>Oracle manipulation.</strong> Moving the price a contract reads, in order to extract value from whatever decision it makes on it.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><strong>GRAIN</strong> is an ERC-20 with no mint function. Residents call <code>harvest()</code> for 100 GRAIN, rate-limited by a cooldown. No admin can print it.</p><p><strong>TownSwap</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> inAfterFee </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> amountIn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10_000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FEE_BPS);          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// FEE_BPS = 30 → 0.3%</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (inAfterFee </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> reserveOut) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (reserveIn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10_000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> inAfterFee);</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>What</th></tr></thead><tbody><tr><td><code>addLiquidity(amountTvd, maxGrain, deadline)</code></td><td>Deposit both at the current ratio; receive shares</td></tr><tr><td><code>removeLiquidity(shares, deadline)</code></td><td>Take your share of both</td></tr><tr><td><code>swapTvdForGrain(amountIn, minOut, deadline)</code></td><td><code>minOut</code> is your slippage protection</td></tr><tr><td><code>swapGrainForTvd(amountIn, minOut, deadline)</code></td><td>The other direction</td></tr><tr><td><code>quote(amountIn, tvdIn)</code></td><td>What this <strong>specific</strong> trade returns</td></tr><tr><td><code>unsafeSpotTvdPerGrain()</code></td><td>The price — note the name</td></tr><tr><td><code>k()</code></td><td>The invariant</td></tr></tbody></table><p><strong>GrainLoans</strong></p><table tabindex="0"><thead><tr><th>Function</th><th>What</th></tr></thead><tbody><tr><td><code>supply(amount)</code> / <code>withdrawSupply(shares)</code></td><td>Lenders provide TVD, earn interest</td></tr><tr><td><code>depositCollateral</code> / <code>withdrawCollateral</code></td><td>GRAIN in and out</td></tr><tr><td><code>borrow(amount)</code></td><td>Up to <code>LTV_BPS</code> of collateral value</td></tr><tr><td><code>repay(amount)</code></td><td>Interest first, folded into debt on every touch</td></tr><tr><td><code>liquidate(borrower, repayAmount)</code></td><td>Anyone, above the threshold, for a bonus</td></tr><tr><td><code>healthFactor(who)</code></td><td>Below 1e18 → liquidatable</td></tr></tbody></table><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><h3 id="the-bug" tabindex="-1">The bug <a class="header-anchor" href="#the-bug" aria-label="Permalink to &quot;The bug&quot;">​</a></h3><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/// </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> HERE IS THE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BUG</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">. The spot price of an AMM is not a price feed: it is a</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">///      snapshot of one pool&#39;s reserves, and reserves are exactly what a trader can change.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> _valueOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> grainAmount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> view</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> returns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (grainAmount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> swap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unsafeSpotTvdPerGrain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1e18</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>One line. It reads a number from a pool, and that number is a function of reserves that anyone with capital can move inside a single transaction.</p><p>The attack, which the repository performs in <code>test_ATTACK_InflateTheCollateralPriceAndWalkAway</code>:</p><ol><li><strong>Pump.</strong> Swap a large amount of TVD for GRAIN. The pool&#39;s TVD reserve rises, its GRAIN reserve falls, and <code>unsafeSpotTvdPerGrain</code> rises with them. In the test the price goes from <strong>1.00 to 3.605 TVD per GRAIN</strong>.</li><li><strong>Borrow.</strong> Deposit GRAIN as collateral. The lender values it at the inflated price and lets you borrow <strong>1081.46 TVD</strong> against collateral genuinely worth <strong>601.71</strong>.</li><li><strong>Dump.</strong> Swap the GRAIN back. The price falls to <strong>1.0028</strong> — near where it started.</li><li><strong>Walk.</strong> The debt stays. Your position is deeply underwater and you do not care, because you are up <strong>1078.6 TVD</strong> and the collateral you abandon is worth less than what you took.</li></ol><p>The loss lands on the lenders who supplied the TVD.</p><p>Nothing here is exotic. No reentrancy, no overflow, no compiler quirk, no admin key. Every call is a documented function used exactly as intended. <strong>The contract is correct and the system is broken</strong>, and that gap is the most valuable thing in this module — most real losses look like this, not like a clever exploit.</p><p>Run it and watch the numbers:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --match-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_ATTACK</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vvv</span></span></code></pre></div><h3 id="why-the-fix-is-not-obvious" tabindex="-1">Why the fix is not obvious <a class="header-anchor" href="#why-the-fix-is-not-obvious" aria-label="Permalink to &quot;Why the fix is not obvious&quot;">​</a></h3><ul><li><strong>&quot;Use a TWAP.&quot;</strong> A time-weighted average over, say, thirty minutes makes the attack cost far more — you must hold the price up for the whole window, exposed to arbitrageurs the entire time. It does not make it impossible, and it makes liquidations lag reality, which is its own risk in a crash.</li><li><strong>&quot;Use an oracle.&quot;</strong> Now you have module 14&#39;s problem, with money on it.</li><li><strong>&quot;Use several sources.&quot;</strong> Better, more complex, and you must decide what to do when they disagree — which is a policy question with no correct answer.</li><li><strong>&quot;Use a deeper pool.&quot;</strong> Raises the cost of the attack in proportion to depth. It is a price, not a barrier, and flash loans mean the attacker need not own the capital.</li></ul><p>There is no line of code that fixes this. That is the lesson.</p><h3 id="the-honest-parts-of-the-design" tabindex="-1">The honest parts of the design <a class="header-anchor" href="#the-honest-parts-of-the-design" aria-label="Permalink to &quot;The honest parts of the design&quot;">​</a></h3><p><strong>Slippage protection is the caller&#39;s job.</strong> Every swap takes <code>minOut</code> and a <code>deadline</code>. A front-runner can see your transaction, trade ahead of it, and leave you a worse price; a <code>minOut</code> you chose is what stops that turning into an unbounded loss. Passing <code>0</code> is passing your wallet to whoever is watching the mempool.</p><p><strong>The liquidation bonus is not generosity.</strong> Without it, nobody would spend gas closing somebody else&#39;s bad position, and bad debt would simply accumulate. Ten percent is a wage for a job the protocol needs done, paid by the borrower who let it happen.</p><p><strong>Interest accrues lazily.</strong> <code>_accrue</code> folds interest into the debt whenever a position is touched. Simple, and it means <code>totalDebt</code> understates reality between touches. Real protocols use a global index that ticks for everyone. Replacing this is one of the exercises, and it is more subtle than it looks.</p><p><strong><code>MINIMUM_LIQUIDITY</code> is burned on the first deposit.</strong> A thousand wei of shares that nobody owns, so the pool can never be fully drained and the share price cannot be manipulated by donating to an empty pool. This is a fix for a real Uniswap V2 attack, carried over deliberately.</p><p><strong>The dangerous function is named <code>unsafeSpotTvdPerGrain</code>.</strong> Not <code>getPrice</code>. If a function returns something that must not be trusted, the name is the cheapest warning you will ever write — and <code>GrainLoans</code> calls it anyway, which is exactly what a real codebase does under deadline.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li><code>harvest()</code> some GRAIN.</li><li>Seed the pool with <code>addLiquidity</code>. Note <code>k</code>.</li><li>Swap a small amount. Check <code>quote</code> first, then compare with what you received.</li><li>Now swap something large — a tenth of the pool. Look at the price you got versus the headline rate. That is slippage, and it is why <code>quote</code> exists.</li><li>Check <code>k</code> after each swap. It only grows.</li><li>Supply TVD to <code>GrainLoans</code> from another account. Deposit GRAIN, borrow, watch <code>healthFactor</code>.</li><li>Borrow to near the limit, then have someone else swing the price and liquidate you.</li></ol><p>Then run the attack:</p><ol start="8"><li>Record <code>unsafeSpotTvdPerGrain()</code>.</li><li>Swap a large amount of TVD for GRAIN. Record it again.</li><li>Deposit collateral and call <code>availableToBorrow</code>. Compare with step 8&#39;s valuation.</li><li>Borrow the maximum. Swap the GRAIN back. Record the price a third time.</li><li>Add up what you hold, and what you owe, and decide whether you would repay.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Swapped(who: 0x…, tvdIn: true, amountIn: 500e18, out: 285e18, reserveTvd: …, reserveGrain: …)</span></span>
<span class="line"><span>CollateralDeposited(who: 0x…, amount: 300e18)</span></span>
<span class="line"><span>Borrowed(who: 0x…, amount: 1081.46e18, debt: 1081.46e18, price: 3.605e18)</span></span>
<span class="line"><span>Swapped(who: 0x…, tvdIn: false, amountIn: 285e18, out: …, reserveTvd: …, reserveGrain: …)</span></span></code></pre></div><p><code>Borrowed</code> records the <strong>price the decision was made at</strong>. That is deliberate: it is the field a post-mortem reads first, and a protocol that does not log the price it trusted cannot explain what happened to it.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>A market maker with an order book gives better prices at size, and an exchange can halt trading, reverse an error, and know its customers.</p><p>AMMs earn their place for <strong>long-tail assets with no professional market maker</strong>, for <strong>permissionless listing</strong>, and because they are <strong>composable</strong> — another contract can trade against them without asking. That last property is also what made this module&#39;s attack possible, and both facts are true at once.</p><p>Lending against volatile collateral, with no identity and no recourse, is a genuinely hard problem that traditional finance solves with underwriting and courts. Over-collateralisation is the on-chain substitute, and it is expensive: you must already have the money to borrow the money.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Price manipulation.</strong> The point.</li><li><strong>Impermanent loss.</strong> Liquidity providers can end up worse off than holding. Nothing here warns them.</li><li><strong>Front-running.</strong> <code>minOut</code> bounds your loss; it does not stop the sandwich.</li><li><strong>Bad debt.</strong> If the price gaps through the threshold faster than liquidators react, the position is underwater and the lenders eat it.</li><li><strong>Interest rate policy.</strong> <code>rateBps</code> is set by an admin. Real protocols use a utilisation curve, and that is an exercise.</li><li><strong>Flash loans.</strong> Not on this chain today — and they only reduce the <em>capital</em> needed for the attack, not its logic.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Using a spot price for anything.</strong> Say it out loud once per project.</li><li><strong>Swapping with <code>minOut = 0</code>.</strong> Free money for a bot.</li><li><strong>Assuming a TWAP is safe.</strong> It raises the cost. Know by how much.</li><li><strong>Liquidation thresholds too close to the LTV.</strong> Ordinary volatility liquidates honest borrowers.</li><li><strong>No liquidation bonus.</strong> Nobody liquidates; bad debt piles up.</li><li><strong>Not burning minimum liquidity.</strong> The empty-pool donation attack.</li><li><strong>Reading reserves instead of <code>balanceOf</code>, or the reverse, inconsistently.</strong> Pick one and be able to say why.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Where does every price in the system come from, and who can move it?</li><li>[ ] How much would it cost to move the price by 2×? By 10×?</li><li>[ ] Can a position be opened and closed profitably within one transaction?</li><li>[ ] Does <code>k</code> ever decrease?</li><li>[ ] Can <code>removeLiquidity</code> take more than a proportional share?</li><li>[ ] What happens to a position the price gaps past with no liquidator watching?</li><li>[ ] Is <code>minOut</code> enforced on every path, including the ones added later?</li><li>[ ] Does interest accrue correctly for a position untouched for a year?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li><strong>Fix the oracle.</strong> Add a TWAP to <code>TownSwap</code> and read it from <code>GrainLoans</code>. Then measure what it now costs to run the attack, and how stale the price is during a real move.</li><li>Add a <strong>utilisation-based interest rate</strong>, so borrowing costs more when the pool is nearly drained.</li><li>Replace lazy accrual with a <strong>global index</strong>, and prove your version matches the old one on a suite of scenarios before you trust it.</li><li>Add a <strong>circuit breaker</strong>: pause borrowing if the price moves more than X% in one block. Then work out who can abuse the pause.</li><li>Write the <strong>incident report</strong> for the attack as if it had happened to a live protocol, using <code>docs/INCIDENT.md</code>. This is the deliverable the labs ask for, and it is the skill that gets people hired.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://uniswap.org/whitepaper.pdf" target="_blank" rel="noreferrer">Uniswap V2 whitepaper</a> — short, and worth reading in full.</li><li><a href="https://docs.uniswap.org/contracts/v2/concepts/core-concepts/oracles" target="_blank" rel="noreferrer">Uniswap V2 oracle design</a> — the TWAP, and its stated limitations.</li><li><a href="https://docs.aave.com/" target="_blank" rel="noreferrer">Aave</a> and <a href="https://docs.compound.finance/" target="_blank" rel="noreferrer">Compound</a> on liquidation mechanics.</li><li>Search for post-mortems of price-oracle manipulation incidents and read three of them. You will notice how many describe exactly the four steps above.</li></ul><p><strong>Next:</strong> <a href="./README">Back to the module index →</a></p>`,69)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
